public class METInventTransferOrderHeaderEntity extends common
{
    // MPJ_28152_CSD_Fulfilment
    // Removed as not in VendInvoiceJournalHeaderEntity, TransferOrderNumber to get populated postGetStagingData method
    
}

Method.Source:
    public void initValue()
    {
        /*if (!this.skipNumberSequenceCheck())
        {
            NumberSeqRecordFieldHandler::enableNumberSequenceControlForField(
                this, fieldNum(METInventTransferOrderHeaderEntity, TransferOrderNumber), InventParameters::numRefTransferId());
        }*/

        this.METCSDTransfer = NoYes::Yes;

        super();
    }

    public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        switch (_dataSourceCtx.name())
        {
            case dataEntityDataSourceStr(METInventTransferOrderHeaderEntity, ShippingLogisticsPostalAddressBaseEntity):
                if (_dataSourceCtx.isAnyEntityFieldSet(this))
                {
                    this.TradeEntitySpecificShippingAddress::mapLogisticsPostalAddressBaseEntityDataSourceToEntity(_dataSourceCtx);
                }
                break;

            case dataEntityDataSourceStr(METInventTransferOrderHeaderEntity, ReceivingLogisticsPostalAddressBaseEntity):
                if (_dataSourceCtx.isAnyEntityFieldSet(this))
                {
                    this.TradeEntitySpecificReceivingAddress::mapLogisticsPostalAddressBaseEntityDataSourceToEntity(_dataSourceCtx);
                }
                break;
        }

        super(_entityCtx, _dataSourceCtx);

        // MPJ_28152_CSD_Fulfilment
        // added, similar to VendInvoiceJournalHeaderEntity 
        if (_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert)
        {
            switch (_dataSourceCtx.name())
            {
                case dataEntityDataSourceStr(METInventTransferOrderHeaderEntity, InventTransferTable):
                    InventTransferTable inventTransferTable = _dataSourceCtx.getBuffer();
                    if (inventTransferTable.isFieldSet(fieldNum(InventTransferTable, TransferId)))
                    {
                        inventTransferTable.fieldState(fieldNum(InventTransferTable, TransferId), FieldState::Defaulted);
                    }
                    break;
            }
        }
    }

    public void mapDataSourceToEntity(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        if (_dataSourceCtx.name() == dataEntityDataSourceStr(METInventTransferOrderHeaderEntity, InventTransferTable))
        {
            InventTransferTable inventTransferTable =  _dataSourceCtx.getBuffer();

            this.TradeEntitySpecificShippingAddress::mapSavedPostalAddressToEntity(_entityCtx,  inventTransferTable.FromPostalAddress, 'ShippingLogisticsPostalAddressBaseEntity');
            this.TradeEntitySpecificReceivingAddress::mapSavedPostalAddressToEntity(_entityCtx,  inventTransferTable.FromPostalAddress, 'ReceivingLogisticsPostalAddressBaseEntity');
        }

        super(_entityCtx, _dataSourceCtx);
    }

    public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        switch (_dataSourceCtx.name())
        {
            case dataEntityDataSourceStr(METInventTransferOrderHeaderEntity, InventTransferTable):
                InventTransferTable inventTransferTable =  _dataSourceCtx.getBuffer();
                
                if (!this.isFieldSet(fieldNum(METInventTransferOrderHeaderEntity, RequestedShippingDate))
                    && !this.isFieldSet(fieldNum(METInventTransferOrderHeaderEntity, RequestedReceiptDate)))
                {
                    SalesCalcAvailableDlvDates::initDateFieldsOrderEntryDeadline(inventTransferTable);
                }

                this.InventTransferOrderEntityMap::setDeliveryDateControlFields(inventTransferTable, fieldNum(InventTransferTable, DeliveryDateControlType));
                break;
        }

        boolean ret = super(_entityCtx, _dataSourceCtx);

        return ret;
    }

    public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        switch (_dataSourceCtx.name())
        {
            case dataEntityDataSourceStr(METInventTransferOrderHeaderEntity, InventTransferTable):
                InventTransferTable inventTransferTable =  _dataSourceCtx.getBuffer();

                this.InventTransferOrderEntityMap::setDeliveryDateControlFields(inventTransferTable, fieldNum(InventTransferTable, DeliveryDateControlType));
                break;
        }

        return super(_entityCtx, _dataSourceCtx);
    }

    public Common findEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        Common ret;

        switch (_dataSourceCtx.name())
        {
            case dataEntityDataSourceStr(METInventTransferOrderHeaderEntity, ShippingLogisticsPostalAddressBaseEntity):
                ret = TradeEntitySpecificShippingAddress::findLogisticsPostalAddressBaseEntityDataSource();
                break;

            case dataEntityDataSourceStr(METInventTransferOrderHeaderEntity, ReceivingLogisticsPostalAddressBaseEntity):
                ret = TradeEntitySpecificReceivingAddress::findLogisticsPostalAddressBaseEntityDataSource();
                break;

            default:
                ret = super(_entityCtx, _dataSourceCtx);
        }

        return ret;
    }

    public boolean validateWrite()
    {
        if (this.RecId)
        {
            InventTransferStatus transferStatus = InventTransferTable::find(this.TransferOrderNumber).TransferStatus;

            if (transferStatus != InventTransferStatus::Created)
            {
                return checkFailed(strFmt("@SCM:InventTransferOrderHeaderEntityUpdateNotAllowed", transferStatus, InventTransferStatus::Created));
            }
        }

        return super();
    }

    // MPJ_28152_CSD_Fulfilment
    // added, similar to VendInvoiceJournalHeaderEntity
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean ret = super(_fieldIdToCheck);

        if (ret)
        {
            switch (_fieldIdToCheck)
            {
                case fieldNum(METInventTransferOrderHeaderEntity, TransferOrderNumber):
                    ret = NumberSeq::numCheckFormat(this.TransferOrderNumber, NumberSeqReference::findReference(extendedtypenum(InventTransferId)).numberSequenceTable());
                    break;
            }
        }

        return ret;
    }

    /// <summary>
    /// MPJ_28152_CSD_Fulfilment
    /// Updates the transfer order header staging table after population.
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">The data management framework definition group being executed.</param>
    /// <remarks>This method is called automatically by the data management framework.</remarks>
    public static void postGetStagingData(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        if (!METInventTransferOrderEntityBase::isTransferOrderNumberSequenceManual())
        {
            METInventTransferOrderHeaderStaging headerStaging;
            METInventTransferOrderEntityBaseTmp transferOrderNumberMap = METInventTransferOrderEntityBase::generateJournalNumbers(_dmfDefinitionGroupExecution/*, headerStaging*/);

            update_recordset headerStaging
                setting TransferOrderNumber = transferOrderNumberMap.NewTransferOrderNumber,
                TransferOrderNumberOld = transferOrderNumberMap.OldTransferOrderNumber
            join NewTransferOrderNumber, OldTransferOrderNumber from transferOrderNumberMap
                where headerStaging.TransferOrderNumber == transferOrderNumberMap.OldTransferOrderNumber
                      && headerStaging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
                      && headerStaging.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId
                      && headerStaging.TransferStatus == DMFTransferStatus::NotStarted;
        }
    }

